// The red row's beat, the reader's 600 ms: only while the Ore Finder is open
// and there are prices to have picked the ore by. A picture holds it still
// (setPlanPulseForShot).
void MinerGUI::keepPlanPulse() {
    if (!planner_) return;
    if (plannerVisible_ && uexEnabled_ && uexPrices_ && !uexPrices_->empty() && !headless_) {
        SetTimer(planner_, TIMER_PLAN_PULSE, 600, nullptr);
    } else {
        KillTimer(planner_, TIMER_PLAN_PULSE);
        planPulse_ = false;
    }
}

