float MinerGUI::rockStripHeight() const {
    if (rockContents_.parts.empty() || !everRead_) return 0.0f;
    // a third line, the SCU of every part, once the panel has said the rock's;
    // and under it what a player on UEX pays for a part of 900 or more
    return (rock_.scu > 0 ? scaleF(54) : scaleF(40)) + (rockMarketLine().empty() ? 0.0f : scaleF(16));
}

// How much of the rock a part is, in SCU: the rock's SCU off the panel times
// the part's share, to two places as the game puts its own figures. Empty
// while the panel has not said the rock's SCU.
static std::wstring partScu(float rockScu, float percent) {
    if (rockScu <= 0 || percent <= 0) return L"";
    const float amount = rockScu * percent / 100.0f;
    if (amount < 0.005f) return L"<0.01";
    wchar_t text[32];
    std::swprintf(text, 32, L"%.2f", amount);
    return text;
}

// What a part comes to, at x, y: the figure bold and white, "SCU" small and
// grey on it, their feet on one line (the overlay draws it the same way)
static void drawAmount(Gdiplus::Graphics& g, const std::wstring& amount, const Gdiplus::Font& figureFont,
                       const Gdiplus::Font& unitFont, float x, float y, float room) {
    Gdiplus::StringFormat noWrap;
    noWrap.SetFormatFlags(Gdiplus::StringFormatFlagsNoWrap);
    Gdiplus::SolidBrush figureBrush(COL_TEXT), unitBrush(COL_TEXT_DIM);
    Gdiplus::RectF figureW;
    g.MeasureString(amount.c_str(), -1, &figureFont, Gdiplus::PointF(0, 0), &figureW);
    const float lift = fontAscent(figureFont) - fontAscent(unitFont);
    g.DrawString(amount.c_str(), -1, &figureFont, Gdiplus::RectF(x, y, room, figureW.Height), &noWrap, &figureBrush);
    const float ux = x + figureW.Width - figureFont.GetSize() * 0.2f;   // GDI+ pads what it measures
    if (ux < x + room) {
        g.DrawString(L"SCU", -1, &unitFont, Gdiplus::RectF(ux, y + lift, x + room - ux, figureW.Height), &noWrap,
                     &unitBrush);
    }
}

// A part's quality in the colour of a rarity: by the band of the game's own
// it rolled into (QUALITY_BAND_EDGES - every material's qualities are made
// with them), as rare among a rock's parts as that rarity is. A common rock's
// part comes in under 600 half the time (Common), at 600 to 699 a third of it
// (Uncommon), at 700 to 799 one time in eight (Rare), at 800 to 899 one in
// thirty (Epic) and at 900 and over one in two hundred (Legendary); a
// legendary rock rolls wider, in the same order. The colours are the ore
// list's rarities, Common in its grey too.
static Rarity qualityRarity(int quality) {
    if (quality >= QUALITY_BAND_EDGES[5]) return Rarity::Legendary;
    if (quality >= QUALITY_BAND_EDGES[4]) return Rarity::Epic;
    if (quality >= QUALITY_BAND_EDGES[3]) return Rarity::Rare;
    if (quality >= QUALITY_BAND_EDGES[2]) return Rarity::Uncommon;
    return Rarity::Common;
}

// ...and the last band, 1000, blinks in the legendary colour: on the beat
// that blinks the looked-for parts, steady while the scan is off and
// nothing beats
Gdiplus::Color MinerGUI::qualityColor(int quality) {
    const Gdiplus::Color colour = getRarityColor(qualityRarity(quality));
    if (quality >= QUALITY_BAND_EDGES[7] && liveModeActive_ && !pulseOn_) {
        return Gdiplus::Color(90, colour.GetR(), colour.GetG(), colour.GetB());
    }
    return colour;
}

// A rock's parts in the order the view lists them: ore by ore, the one there
// is most of first - in a whole rock its own - and of an ore's parts the
// better first. The panel's own order is no order: it lists Silicon over a
// Hephaestanite rock's Hephaestanite. The inert rest is not among them.
static std::vector<const RockPartRead*> rockPartsInOrder(const RockContents& contents) {
    std::vector<const RockPartRead*> parts;
    for (const RockPartRead& part : contents.parts) {
        if (!part.inert) parts.push_back(&part);
    }
    const auto total = [&](const std::string& ore) {
        float sum = 0;
        for (const RockPartRead* p : parts) {
            if (p->ore == ore) sum += p->percent;
        }
        return sum;
    };
    std::stable_sort(parts.begin(), parts.end(), [&](const RockPartRead* a, const RockPartRead* b) {
        if (a->ore != b->ore) {
            const float ta = total(a->ore), tb = total(b->ore);
            return ta != tb ? ta > tb : a->ore < b->ore;
        }
        return a->quality > b->quality;
    });
    return parts;
}

void MinerGUI::updateResults(int signature, const std::vector<AnalysisResult>& results,
                             double confidence, bool outOfPlace) {
    resultsOutOfPlace_ = outOfPlace;
    currentSignature_ = signature;
    currentResults_ = results;
    currentConfidence_ = confidence;
    // A reading off the screen is proof the capture works, which retires the
    // borderless-window notice for this session. A typed number is not - it
    // says nothing about what the app can see, and confidence is below zero
    // for those.
    if (signature > 0 && confidence >= 0 && !everRead_) {
        everRead_ = true;
        // The notice retiring moves everything below it up by extraTop(),
        // and the four nav buttons are real child windows - they do not
        // move because the painting changed.
        layoutControls();
    }
    bool stillListed = false;
    for (const auto& r : results) {
        if (r.name == selectedMineral_) { stillListed = true; break; }
    }
    if (!stillListed) selectedMineral_ = results.empty() ? "" : results.front().name;
    InvalidateRect(hwnd_, nullptr, TRUE);
}

void MinerGUI::setCurrentSystem(const std::string& system) {
    currentSystem_ = system;
    InvalidateRect(hwnd_, nullptr, TRUE);
}

bool MinerGUI::trackHover(HWND hwnd, POINT& slot, LPARAM lParam) {
    const POINT at = {(LONG)(short)LOWORD(lParam), (LONG)(short)HIWORD(lParam)};
    // Ask Windows to say when the mouse leaves, or the last row stays lit
    // after the pointer has gone somewhere else entirely.
    TRACKMOUSEEVENT leave = {sizeof(leave), TME_LEAVE, hwnd, 0};
    TrackMouseEvent(&leave);
    if (slot.x >= 0 && std::abs(at.y - slot.y) < 3 && std::abs(at.x - slot.x) < 6) {
        slot = at;
        return false;
    }
    slot = at;
    InvalidateRect(hwnd, nullptr, FALSE);
    return true;
}

void MinerGUI::clearHover(HWND hwnd, POINT& slot) {
    if (slot.x < 0) return;
    slot = {-1, -1};
    InvalidateRect(hwnd, nullptr, FALSE);
}

bool MinerGUI::processMessages() {
    ensureHotkeys();
    MSG msg;
    while (PeekMessage(&msg, nullptr, 0, 0, PM_REMOVE)) {
        if (msg.message == WM_QUIT) {
            isOpen_ = false;
            return false;
        }

        // The system-wide hotkey arrives as a thread message, so it is caught
        // here rather than in the window procedure
        if (msg.message == WM_HOTKEY && msg.wParam == HOTKEY_KEEP_RECORDING) {
            if (keepRecordingCallback_) keepRecordingCallback_();
            continue;
        }
        if (msg.message == WM_HOTKEY && msg.wParam == HOTKEY_SNAPSHOT) {
            if (snapshotCallback_) snapshotCallback_();
            continue;
        }

        // Ctrl+V inside the notebook, when what is on the clipboard is a
        // PICTURE. Text paste is left alone - that is the rich edit control's
        // own business - but a bitmap has nowhere to go in a plain text note
        // and would otherwise be dropped silently. A clipboard holding both is
        // text: text is what was copied.
        if (msg.message == WM_KEYDOWN && msg.wParam == 'V' && notes_ &&
            (GetKeyState(VK_CONTROL) & 0x8000) &&
            (msg.hwnd == notes_ || msg.hwnd == notesEdit_) && noteIndex_ >= 0 &&
            !IsClipboardFormatAvailable(CF_UNICODETEXT) &&
            (IsClipboardFormatAvailable(CF_DIB) || IsClipboardFormatAvailable(CF_HDROP))) {
            pasteIntoOpenNote();
            continue;
        }

        // The notebook's boxes: Enter and Esc mean "done" and "drop it" to the
        // window, and a plain edit control would swallow both
        if (msg.message == WM_KEYDOWN && notesName_ && msg.hwnd == notesName_) {
            if (msg.wParam == VK_RETURN) {
                commitNaming();
                continue;
            }
            if (msg.wParam == VK_ESCAPE) {
                nameMode_ = 0;
                ShowWindow(notesName_, SW_HIDE);
                SetFocus(notes_);
                InvalidateRect(notes_, nullptr, TRUE);
                continue;
            }
        }
        // The suggestion list answers to the keyboard while it is up
        // The wheel goes to whatever holds the focus, which is the note, not
        // the list - so the list gets its turn here, while it is under the
        // pointer. Without this there is no reaching entry 23 with a mouse.
        if (msg.message == WM_MOUSEWHEEL && suggesting() && notesSuggest_) {
            RECT listRc = {};
            GetWindowRect(notesSuggest_, &listRc);
            if (PtInRect(&listRc, msg.pt)) {
                moveSuggestion(GET_WHEEL_DELTA_WPARAM(msg.wParam) > 0 ? -3 : 3, false);
                continue;
            }
        }
        if (msg.message == WM_KEYDOWN && notesEdit_ && msg.hwnd == notesEdit_ && suggesting()) {
            if (msg.wParam == VK_RETURN) {
                acceptSuggestion();
                continue;
            }
            if (msg.wParam == VK_ESCAPE) {
                hideSuggestions();
                continue;
            }
            if (msg.wParam == VK_DOWN || msg.wParam == VK_UP) {
                moveSuggestion(msg.wParam == VK_DOWN ? 1 : -1, true);
                continue;
            }
            if (msg.wParam == VK_NEXT || msg.wParam == VK_PRIOR) {
                moveSuggestion(msg.wParam == VK_NEXT ? SUGGEST_ROWS : -SUGGEST_ROWS, false);
                continue;
            }
        }
        if (msg.message == WM_KEYDOWN && notesEdit_ && msg.hwnd == notesEdit_) {
            // Ctrl+A is not built into a plain edit control
            if (msg.wParam == 'A' && (GetKeyState(VK_CONTROL) & 0x8000)) {
                SendMessageW(notesEdit_, EM_SETSEL, 0, -1);
                continue;
            }
            if (msg.wParam == VK_ESCAPE) {
                saveNote();
                SetFocus(notes_);
                continue;
            }
        }

        // The window has two fields that are painted rather than built out of
        // an edit control: the ore search, and the crafted-% box in the
        // loadout card. While either has the cursor, every key belongs to it.
        // Two things below would otherwise eat it: the shortcuts (B would open
        // the blueprints in the middle of typing "Beryl"), and IsDialogMessage,
        // which takes a bare key on a plain window for a mnemonic, answers
        // "handled", and so TranslateMessage never runs and no WM_CHAR ever
        // reaches the window at all. Giving a field the focus is not enough -
        // the key never gets as far as the focus - so every painted field has
        // to be listed here.
        //
        // Esc and Enter still arrive either way: the window procedure closes
        // the list and leaves the field on them.
        const bool typingHere = (lookingOpen_ || (loadoutOpen_ && (craftedEditing_ || nameEditing_))) &&
            msg.hwnd == hwnd_ &&
            (msg.message == WM_KEYDOWN || msg.message == WM_KEYUP ||
             msg.message == WM_CHAR || msg.message == WM_SYSKEYDOWN);

        // Window-level hotkeys (skip when typing into an edit control)

        if (!typingHere && msg.message == WM_KEYDOWN &&
            (msg.hwnd == hwnd_ || GetParent(msg.hwnd) == hwnd_)) {
            // The first start's UEX offer has the keys while it is up: Esc
            // skips it, and no other key opens anything behind it
            if (uexWelcome_.step) {
                if (msg.wParam == VK_ESCAPE) closeUexWelcome();
                continue;
            }
            wchar_t cls[16] = {};
            GetClassNameW(msg.hwnd, cls, 16);
            const bool inEdit = _wcsicmp(cls, L"Edit") == 0;
            // An amount being typed is an edit field in all but name:
            // these shortcuts run BEFORE the window sees the key, so
            // without this a stray letter opens another window in the
            // middle of entering a figure.
            const bool inAmount = (refineryTyping_ >= 0 && msg.hwnd == refinery_);

            if (!inEdit && !inAmount) {
                switch (msg.wParam) {
                    case 'L':
                        SendMessage(hwnd_, WM_COMMAND, MAKEWPARAM(ID_BTN_LIVEMODE, BN_CLICKED),
                                    (LPARAM)btnLiveMode_);
                        continue;
                    case 'O':
                        SendMessage(hwnd_, WM_COMMAND, MAKEWPARAM(ID_BTN_OVERLAY, BN_CLICKED),
                                    (LPARAM)btnOverlay_);
                        continue;
                    case VK_F1:
                        showKeys(!keysOpen_);
                        continue;
                    case VK_OEM_PLUS:
                    case VK_ADD:
                        if (GetKeyState(VK_CONTROL) & 0x8000) {
                            stepUiScale(1);
                            continue;
                        }
                        break;
                    case VK_OEM_MINUS:
                    case VK_SUBTRACT:
                        if (GetKeyState(VK_CONTROL) & 0x8000) {
                            stepUiScale(-1);
                            continue;
                        }
                        break;
                    case '0':
                        if (GetKeyState(VK_CONTROL) & 0x8000) {
                            setUiScale(100);
                            continue;
                        }
                        break;
                    case VK_DOWN:
                    case VK_UP:
                    case VK_NEXT:
                    case VK_PRIOR:
                    case VK_HOME:
                    case VK_END:
                        // The keys that mean the same as the wheel, while the
                        // card is up; they do their usual work otherwise
                        if (whatsNewOpen_) {
                            const float page = whatsNewView_ - scaleF(24);
                            if (msg.wParam == VK_HOME) scrollWhatsNew(-whatsNewContent_);
                            else if (msg.wParam == VK_END) scrollWhatsNew(whatsNewContent_);
                            else if (msg.wParam == VK_NEXT) scrollWhatsNew(page);
                            else if (msg.wParam == VK_PRIOR) scrollWhatsNew(-page);
                            else scrollWhatsNew(msg.wParam == VK_DOWN ? scaleF(40) : -scaleF(40));
                            continue;
                        }
                        break;
                    case VK_ESCAPE:
                        if (whatsNewOpen_) {
                            showWhatsNew(false);
                            continue;
                        }
                        if (keysOpen_) {
                            showKeys(false);
                            continue;
                        }
                        if (aboutOpen_) {
                            showAbout(false);
                            continue;
                        }
                        break;
                    case 'B':
                        toggleCrafting();
                        continue;
                    case 'G':
                        toggleGrind();
                        continue;
                    case 'N':
                        toggleNotes();
                        continue;
                    case 'F':
                        togglePlanner();
                        continue;
                    case 'R':
                        toggleRefinery();
                        continue;
                    case 'Q':
                        PostMessage(hwnd_, WM_CLOSE, 0, 0);
                        continue;
                }
            }
        }

        if (!typingHere && IsDialogMessage(hwnd_, &msg)) {
            continue;
        }
        TranslateMessage(&msg);
        DispatchMessage(&msg);
    }
    return isOpen_;
}

bool MinerGUI::isOpen() const {
    return isOpen_;
}

// The overlay is kept out of screen captures while the scan runs, and while
// the player is at a commodity terminal with a picture owed to UEX - and
// only then: otherwise Bedrock captures nothing it could see itself in, and
// a window kept out shows in Virtual Desktop's stream as "Protected content
// blocked". What keeping it out costs the compositor has not been measured.
void MinerGUI::keepOutOfCaptures() {
#ifdef _WIN32
    if (hwnd_) {
        SetWindowDisplayAffinity(hwnd_, overlayMode_ && (liveModeActive_ || tradeWatch_) ? WDA_EXCLUDEFROMCAPTURE
                                                                                          : WDA_NONE);
    }
#endif
}

void MinerGUI::setTradeWatch(bool on) {
    tradeWatch_ = on;
    keepOutOfCaptures();
}

void MinerGUI::setLiveModeActive(bool active) {
    liveModeActive_ = active;
    keepOutOfCaptures();
    SetWindowTextW(btnLiveMode_, active ? L"Live on" : L"Live off");
    if (active) {
        SetTimer(hwnd_, 1, 600, nullptr);
    } else {
        KillTimer(hwnd_, 1);
        pulseOn_ = false;
    }
    InvalidateRect(hwnd_, nullptr, TRUE);
    InvalidateRect(btnLiveMode_, nullptr, TRUE);
}

